const now = new Date();
const weekNumber = Math.ceil((((now - new Date(now.getFullYear(),0,1)) / 86400000) + new
Date(now.getFullYear(),0,1).getDay()+1)/7);

return [{
  json: {
    runId: `digest-${now.getFullYear()}-W${String(weekNumber).padStart(2, '0')}-${Date.now()}`,
    weekYear: now.getFullYear(),
    weekNumber: weekNumber,
    generatedAt: now.toISOString()
  }
}];

const news = $('Postgres: Load Week\'s News').all().map(item => item.json);
const portfolio = $('Postgres: Load Portfolio').all().map(item => item.json);
const patterns = $('Postgres: Load Patterns').all().map(item => item.json);
const runInfo = $('Generate Run ID').first().json;

// Format portfolio context
const portfolioContext = portfolio.map(p => {
  let context = `${p.symbol} | ${p.security_name} | ${p.asset_class}`;
  if (p.thesis) context += `\n  Thesis: ${p.thesis}`;
  if (p.time_horizon) context += `\n  Horizon: ${p.time_horizon}`;
  if (p.triggers && p.triggers.length > 0) {
    context += `\n  Triggers: ${JSON.stringify(p.triggers)}`;
  }
  return context;
}).join('\n\n');

// Format news summary
const newsSummary = news.map((n, i) => {
  const symbols = Array.isArray(n.symbols_impacted) ? n.symbols_impacted.join(', ') : 'N/A';
  const categories = Array.isArray(n.categories) ? n.categories.join(', ') : 'N/A';
  return `[${i + 1}] ${n.email_subject || 'Manual Input'}
  Priority: ${n.triage_priority} | Score: ${n.composite_score || 'N/A'}
  Symbols: ${symbols}
  Categories: ${categories}
  Summary: ${n.triage_summary || n.analysis_summary || 'No summary'}
  ${n.alert_sent ? `⚡ ALERTED: ${n.alert_reason}` : ''}`;
}).join('\n\n');

// Format pattern history
const patternSummary = patterns.length > 0
  ? patterns.map(p =>
      `${p.symbol} | ${p.category}: ${p.occurrence_count}x (avg score: ${p.avg_composite_score || 'N/A'})`
    ).join('\n')
  : 'No recent patterns recorded.';

return [{
  json: {
    runInfo,
    newsCount: news.length,
    portfolioContext,
    newsSummary,
    patternSummary,
    portfolioSymbols: portfolio.map(p => p.symbol),
    rawNews: news,
    rawPatterns: patterns
  }
}];

