const context = $('Format: Weekly Context').first().json;
const rawOutput = $input.first().json;

let parsed;
try {
  // AI Agent returns { output: "json string" }
  let textContent = rawOutput.output;

  // Parse the JSON string
  parsed = JSON.parse(textContent);

} catch (e) {
  parsed = {
    weekSummary: "Unable to generate weekly analysis due to processing error: " + e.message,
    requiresAttention: [],
    monitor: [],
    patternsToNote: [],
    weekAhead: {
      keyEvents: [],
      suggestedFocus: [],
      riskFactors: []
    },
    noActionNeeded: context.portfolioSymbols || [],
    parseError: e.message
  };
}

// Validate and ensure arrays exist
const validated = {
  weekSummary: parsed.weekSummary || "No summary available.",
  requiresAttention: Array.isArray(parsed.requiresAttention) ? parsed.requiresAttention : [],
  monitor: Array.isArray(parsed.monitor) ? parsed.monitor : [],
  patternsToNote: Array.isArray(parsed.patternsToNote) ? parsed.patternsToNote : [],
  weekAhead: {
    keyEvents: Array.isArray(parsed.weekAhead?.keyEvents) ? parsed.weekAhead.keyEvents : [],
    suggestedFocus: Array.isArray(parsed.weekAhead?.suggestedFocus) ? parsed.weekAhead.suggestedFocus : [],
    riskFactors: Array.isArray(parsed.weekAhead?.riskFactors) ? parsed.weekAhead.riskFactors : []
  },
  noActionNeeded: Array.isArray(parsed.noActionNeeded) ? parsed.noActionNeeded : []
};

return [{
  json: {
    analysis: validated,
    hasParseError: !!parsed.parseError,
    ...context
  }
}];

const data = $input.first().json;
