  for (const item of analysis.requiresAttention) {
    const categories = Array.isArray(item.categories) ? item.categories.join(', ') : '';
    const keyPoints = Array.isArray(item.keyPoints) ? item.keyPoints : [];

    message += `<b>${esc(item.symbol)}</b> | ${esc(categories)}
├─ ${item.newsCount} news item(s)
├─ Thesis: <b>${esc(item.thesisImpact?.toUpperCase())}</b>
`;
    for (const point of keyPoints) {
      message += `├─ ${esc(point)}
`;
    }
    message += `└─ <i>${esc(item.suggestedAction)}</i>

`;
  }
}

// Monitor section
if (analysis.monitor.length > 0) {
  message += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🟡 <b>MONITOR (${analysis.monitor.length})</b>
━━━━━━━━━━━━━━━━━━━━━━━━━━━━

`;
  for (const item of analysis.monitor) {
    message += `<b>${esc(item.symbol)}</b> | ${item.newsCount} item(s)
└─ ${esc(item.summary)} | <i>${esc(item.suggestedAction)}</i>

`;
  }
}

// Patterns to note
if (analysis.patternsToNote.length > 0) {
  message += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━
📈 <b>PATTERNS</b>
━━━━━━━━━━━━━━━━━━━━━━━━━━━━

`;
  for (const pattern of analysis.patternsToNote) {
    message += `• ${esc(pattern)}
`;
  }
  message += `
`;
}

// Week Ahead
const weekAhead = analysis.weekAhead;
if (weekAhead.keyEvents.length > 0 || weekAhead.suggestedFocus.length > 0) {
  message += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━
📅 <b>WEEK AHEAD</b>
