`;
  if (weekAhead.keyEvents.length > 0) {
    message += `<b>Key Events:</b>
`;
    for (const event of weekAhead.keyEvents) {
      message += `• ${esc(event)}
`;
    }
  }
  if (weekAhead.suggestedFocus.length > 0) {
    message += `
<b>Focus Areas:</b>
`;
    for (const focus of weekAhead.suggestedFocus) {
      message += `• ${esc(focus)}
`;
    }
  }
  if (weekAhead.riskFactors.length > 0) {
