━━━━━━━━━━━━━━━━━━━━━━━━━━━━

${analysis.noActionNeeded.join(', ')}

`;
}

// Footer
message += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Support this project ☕
buymeacoffee.com/fabcarvalho`;

return [{
  json: {
    ...data,
    telegramMessage: message
  }
}];

const data = $('Guard: Weekly Analysis').first().json;
const rawNews = data.rawNews || [];

// Build pattern updates from news items
const patternMap = {};

for (const news of rawNews) {
  const symbols = Array.isArray(news.symbols_impacted) ? news.symbols_impacted : [];
  const categories = Array.isArray(news.categories) ? news.categories : [];
  const compositeScore = news.composite_score || 0;

  // Get thesis impacts
  const thesisImpacts = Array.isArray(news.thesis_impacts) ? news.thesis_impacts : [];

  for (const symbol of symbols) {
    for (const category of categories) {
      const key = `${symbol}|${category}`;

      if (!patternMap[key]) {
        patternMap[key] = {
          symbol,
          category,
          totalScore: 0,
          count: 0,
          validates: 0,
          challenges: 0,
          neutral: 0
        };
      }

      patternMap[key].totalScore += compositeScore;
      patternMap[key].count += 1;

      // Check thesis impact for this symbol
      const impact = thesisImpacts.find(t => t.symbol === symbol);
      if (impact) {
        if (impact.impact === 'validates') patternMap[key].validates += 1;
        else if (impact.impact === 'challenges') patternMap[key].challenges += 1;
        else patternMap[key].neutral += 1;
      } else {
        patternMap[key].neutral += 1;
      }
    }
  }
}

const patterns = Object.values(patternMap);

if (patterns.length === 0) {
  return [{ json: { hasPatterns: false, patterns: [] } }];
}

return [{
  json: {
    hasPatterns: true,
    patterns
  }
}];

