const runInfo = $('Generate Run ID').first().json;
const guardData = $('Guard: Weekly Analysis').first().json;
const analysis = guardData.analysis;

// Build symbols array in PostgreSQL format
const symbols = [
  ...analysis.requiresAttention.map(r => r.symbol),
  ...analysis.monitor.map(m => m.symbol)
];
const symbolsArray = '{' + symbols.join(',') + '}';

// Escape single quotes for SQL
const esc = (str) => String(str || '').replace(/'/g, "''");

return [{
  json: {
    run_id: runInfo.runId,
    week_year: runInfo.weekYear,
    week_number: runInfo.weekNumber,
    news_items_count: guardData.newsCount,
    symbols_covered: symbolsArray,
    digest_summary: esc(analysis.weekSummary),
    requires_attention: JSON.stringify(analysis.requiresAttention).replace(/'/g, "''"),
    monitor_list: JSON.stringify(analysis.monitor).replace(/'/g, "''"),
    week_ahead_outlook: JSON.stringify(analysis.weekAhead).replace(/'/g, "''"),
    ai_model_used: 'gpt-4o'
  }
}];
